import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});

test('bulk discount rounds the half yen up', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 11, qty: 1 }));
  assert.equal(total(lines), 105); // 110 * 0.95 = 104.5
});

// issue #12: the customer's discount applies once.
test('a 10% customer pays 900 for a 1,000 yen cart below 10 lines', () => {
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900); // 1,000 * 0.9
  const nineLines = [...Array.from({ length: 8 }, () => ({ price: 100, qty: 1 })), { price: 200, qty: 1 }];
  assert.equal(total(nineLines, 0.1), 900); // still below 10 lines: no bulk discount
});

test('from 10 lines, 5% bulk discount applies once after the customer discount', () => {
  const lines = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines, 0.1), 8550); // 10,000 * 0.9 = 9,000, then * 0.95
});

test('totals at discount rate 0 stay as they were', () => {
  const lines = (n) => Array.from({ length: n }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(lines(9), 0), 9000); // below 10 lines: list price
  assert.equal(total(lines(10), 0), 9500); // 10 lines: 5% off
  assert.equal(total(lines(10)), total(lines(10), 0)); // omitted rate means 0
});

